  printf("\n========================================\n");
  printf("  ESP32-P4 UART Test Application\n");
  printf("========================================\n");
  printf("UART Port: %d\n", UART_PORT);
  printf("Baud Rate: %d\n", UART_BAUD);

  /* Test 1: UART Write */

  ret = test_uart_write();
  if (ret == 0)
    {
      passed++;
    }
  else
    {
      failed++;
    }

  /* Test 2: UART Read */

  ret = test_uart_read();
  if (ret == 0)
    {
      passed++;
    }
  else
    {
      failed++;
    }

  /* Test 3: UART Loopback */

  ret = test_uart_loopback();
  if (ret == 0)
    {
      passed++;
    }
  else
    {
      failed++;
    }

  /* Print summary */

  printf("\n========================================\n");
  printf("  Test Summary\n");
  printf("========================================\n");
  printf("Passed: %d\n", passed);
  printf("Failed: %d\n", failed);
  printf("Total:  %d\n", passed + failed);
  printf("Result: %s\n", failed == 0 ? "ALL TESTS PASSED" : "SOME TESTS FAILED");
  printf("========================================\n");

  return failed == 0 ? 0 : 1;
}

